public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles N must be non-negative.");
    }
    // The formula to calculate the maximum number of regions
    // formed by N triangles is given by:
    // R(N) = 2 + 3 * N + N * (N - 1) / 2
    // This formula is derived from the fact that each new triangle
    // can intersect with all previous triangles in 3 new edges,
    // adding 3 * N new regions, plus the regions formed by the
    // intersections of the new triangle with the previous ones.
    return 2 + 3 * N + N * (N - 1) / 2;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    // The formula to calculate the maximum number of regions
    // created by N triangles is derived from the pattern:
    // R(N) = R(N-1) + 2N
    // R(0) = 1
    // This simplifies to R(N) = N^2 + N + 2
    return N * N + N + 2;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative.");
    }
    if (N == 0) {
        return 1; // No triangles, only one region (the whole plane).
    }
    // Using the formula for maximum regions created by N triangles
    // R(N) = N * (N + 1) / 2 + 1
    return N * (N + 1) / 2 + 1;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    // The formula to calculate the maximum number of regions is 2^(N+1) - N - 1
    // This is derived from the pattern observed in the problem.
    return (1 << (N + 1)) - N - 1;
}

