    }

    boolean[][] visited = new boolean[n][n];
    boolean result = dfs(start[0], start[1], end[0], end[1], visited, paths, n);
    return result ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int currentX, int currentY, int endX, int endY, boolean[][] visited, int[][] paths, int n) {
    if (currentX == endX && currentY == endY) {
        return true;
    }

    if (currentX < 0 || currentX >= n || currentY < 0 || currentY >= n || visited[currentX][currentY]) {
        return false;
    }

    visited[currentX][currentY] = true;

    for (int[] path : paths) {
        int nextX = currentX + path[0];
        int nextY = currentY + path[1];
        if (dfs(nextX, nextY, endX, endY, visited, paths, n)) {
            return true;
        }
    }

    visited[currentX][currentY] = false;
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start.length != 2 || end.length != 2 || paths == null) {
        return "cannot be travelled";
