    boolean[][] maze = new boolean[n][n];
    boolean[][] visited = new boolean[n][n];
    for (int[] path : paths) {
        if (path.length != 4 || path[0] < 0 || path[0] >= n || path[1] < 0 || path[1] >= n ||
            path[2] < 0 || path[2] >= n || path[3] < 0 || path[3] >= n) {
            continue;
        }
        maze[path[0]][path[1]] = true;
        maze[path[2]][path[3]] = true;
    }
    return canReachEnd(start[0], start[1], end[0], end[1], maze, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canReachEnd(int x, int y, int endX, int endY, boolean[][] maze, boolean[][] visited) {
    if (x == endX && y == endY) {
        return true;
    }
    if (x < 0 || x >= maze.length || y < 0 || y >= maze[0].length || !maze[x][y] || visited[x][y]) {
        return false;
    }
    visited[x][y] = true;
    return canReachEnd(x + 1, y, endX, endY, maze, visited) ||
           canReachEnd(x - 1, y, endX, endY, maze, visited) ||
           canReachEnd(x, y + 1, endX, endY, maze, visited) ||
           canReachEnd(x, y - 1, endX, endY, maze, visited);
}

