public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    if (!isValidCoordinate(start, n) || !isValidCoordinate(end, n)) {
        return "cannot be travelled";
    }

    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]][start[1]] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();

        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] direction : directions) {
            int newX = current[0] + direction[0];
            int newY = current[1] + direction[1];

            if (isValidCoordinate(new int[]{newX, newY}, n) && !visited[newX][newY]) {
                if (isPathAccessible(current, new int[]{newX, newY}, paths)) {
                    queue.offer(new int[]{newX, newY});
                    visited[newX][newY] = true;
                }
            }
        }
    }

    return "cannot be travelled";
}

private static boolean isValidCoordinate(int[] coordinate, int n) {
    return coordinate[0] >= 0 && coordinate[0] < n && coordinate[1] >= 0 && coordinate[1] < n;
}

private static boolean isPathAccessible(int[] from, int[] to, int[][] paths) {
    for (int[] path : paths) {
        if ((path[0] == from[0] && path[1] == from[1] && path[2] == to[0] && path[3] == to[1]) ||
            (path[0] == to[0] && path[1] == to[1] && path[2] == from[0] && path[3] == from[1])) {
            return true;
        }
    }
    return false;
}

