public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    int n = nums.length;
    for (int num : nums) {
        totalSum += num;
    }

    // Try to find a subset of size s (1 <= s <= n/2) with sum = totalSum * s / n
    boolean[][] isPossible = new boolean[n / 2 + 1][totalSum + 1];
    int[][] count = new int[n / 2 + 1][totalSum + 1];
    isPossible[0][0] = true;
    count[0][0] = 1;

    for (int num : nums) {
        for (int s = n / 2; s >= 1; s--) {
            for (int sum = 0; sum <= totalSum - num; sum++) {
                if (isPossible[s - 1][sum]) {
                    isPossible[s][sum + num] = true;
                    count[s][sum + num] += count[s - 1][sum];
                }
            }
        }
    }

    for (int s = 1; s <= n / 2; s++) {
        if (totalSum * s % n == 0 && isPossible[s][totalSum * s / n]) {
            // We found a subset with the required sum
            int subsetSum = totalSum * s / n;
            if (count[s][subsetSum] < (1 << s)) {
                return true;
            }
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n / 2 + 1][n + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int k = 0; k <= sum; k++) {
                if (dp[j - 1][i - 1][k]) {
                    dp[j][i][k + num] = true;
                    dp[j][i][k] = true;
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[i][n][sum * i / n]) {
            return true;
        }
    }

    return false;
}

