        "..-", "...-", ".--", "-..-", "-.--", "--.."
    };

    Set<String> transformations = new HashSet<>();

    for (String word : words) {
        StringBuilder morseWord = new StringBuilder();
        for (char c : word.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                morseWord.append(morseCodes[c - 'a']);
            } else {
                throw new IllegalArgumentException("Invalid character in word: " + c);
            }
        }
        transformations.add(morseWord.toString());
    }

    return transformations.size();
}

public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) return false;

    int total = 1 << k; // 2^k possible binary strings
    boolean[] seen = new boolean[total];

    for (int i = 0; i <= s.length() - k; i++) {
        int val = 0;
        for (int j = 0; j < k; j++) {
            val = val * 2 + (s.charAt(i + j) - '0');
        }
        seen[val] = true;
    }

    for (boolean check : seen) {
        if (!check) return false;
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }

    int max = 1 << k; // This is 2^k, the total number of binary strings of length k
    boolean[] seen = new boolean[max];

    for (int i = 0; i <= s.length() - k; i++) {
        int val = 0;
        for (int j = i; j < i + k; j++) {
            val = val * 2 + (s.charAt(j) - '0');
        }
        seen[val] = true;
    }

    for (boolean b : seen) {
        if (!b) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) return false;

    int totalPossibleCodes = 1 << k; // 2^k
    boolean[] found = new boolean[totalPossibleCodes];

    int value = 0, mask = totalPossibleCodes - 1;

    for (int i = 0; i < s.length(); i++) {
        value = (value << 1) & mask | (s.charAt(i) - '0');
        if (i >= k - 1 && !found[value]) {
            found[value] = true;
            totalPossibleCodes--;
        }
        if (totalPossibleCodes == 0) return true;
    }

    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < (1 << k) + k - 1) {
        return false;
    }

    Set<Integer> seen = new HashSet<>();
    int allOnes = (1 << k) - 1;
    int hashVal = 0;

    for (int i = 0; i < s.length(); i++) {
        hashVal = ((hashVal & allOnes) << 1) + (s.charAt(i) - '0');
        if (i >= k - 1 && seen.add(hashVal) && seen.size() == (1 << k)) {
            return true;
        }
    }

    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < (1 << k) + k - 1) {
        return false;
    }

    Set<String> set = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        set.add(s.substring(i, i + k));
        if (set.size() == (1 << k)) {
            return true;
        }
    }
    return false;
}

