public int minInsertions(String s) {
    int insertions = 0; // To count the number of insertions needed
    int leftBrackets = 0; // To count the number of unmatched '('

    for (char c : s.toCharArray()) {
        if (c == '(') {
            leftBrackets++; // Increment for every '('
        } else {
            // For every ')'
            if (leftBrackets > 0) {
                leftBrackets--; // Match with the last unmatched '('
            } else {
                insertions++; // Need to insert a '(' to match this ')'
            }
        }
    }

    // Every unmatched '(' needs a ')'
    insertions += leftBrackets;

    return insertions;
}

public int minInsertions(String s) {
    int openCount = 0; // To count the number of unmatched '('
    int insertions = 0; // To count the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            openCount++; // Increment count for every '('
        } else {
            // Every ')' should match with a '(' from the left
            if (openCount > 0) {
                openCount--; // Match current ')' with a previous '('
            } else {
                insertions++; // Need to insert a '(' to match current ')'
            }

            // Check for two consecutive ')'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')' since they can form a pair
            } else {
                insertions++; // Need to insert a ')' to form a pair with current ')'
            }
        }
    }

    // Every unmatched '(' needs a matching ')'
    insertions += openCount * 2;

    return insertions;
}

public int minInsertions(String s) {
    int left = 0; // To keep track of unmatched '('
    int insertions = 0; // To count the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            left++;
        } else {
            // For each ')', we need a matching '('
            if (left > 0) {
                left--;
            } else {
                // If no matching '(', we need to insert one
                insertions++;
            }
            // Check if we have two consecutive ')'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')'
            } else {
                // If not, we need to insert one to balance
                insertions++;
            }
        }
    }
    // Add remaining unmatched '(' with their corresponding ')'
    insertions += left * 2;
    return insertions;
}

public int minInsertions(String s) {
    int open = 0; // To keep track of the number of '(' needed
    int insertions = 0; // To count the number of insertions

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open += 2; // Each '(' needs two ')'
            // If open is odd, we need to insert a ')' to make it even
            if (open % 2 == 1) {
                insertions++;
                open--; // One ')' is inserted
            }
        } else if (c == ')') {
            open--; // Each ')' cancels one '('
            if (open == -1) {
                insertions++; // Need to insert a '(' to balance
                open = 1; // One '(' is inserted, so we need one more ')'
            }
        }
    }

    return insertions + open; // Add remaining open needed
}

public int minInsertions(String s) {
    int leftBalance = 0; // Tracks the number of unmatched '('
    int rightNeeded = 0; // Tracks the number of ')' needed to balance current '('

    for (char c : s.toCharArray()) {
        if (c == '(') {
            // Each '(' can pair with two ')', so we need one more ')' to pair with this '('
            if (rightNeeded % 2 == 1) {
                // If we have an odd number of ')' needed, we need to add one '(' to pair with the first of these ')'
                leftBalance++;
                rightNeeded--;
            }
            // We now need two ')' to balance this '('
            rightNeeded += 2;
        } else { // c == ')'
            rightNeeded--;
            if (rightNeeded == -1) {
                // We have more ')' than needed, so we need to add one '(' to balance
                leftBalance++;
                // Reset rightNeeded to 1 because the current ')' is unpaired
                rightNeeded = 1;
            }
        }
    }

    // Total insertions needed is the sum of leftBalance and any remaining rightNeeded (divided by 2)
    return leftBalance + rightNeeded;
}

