public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("Input k must be a positive integer.");
    }

    // Generate Fibonacci numbers less than or equal to k
    int a = 1, b = 1;
    while (b <= k) {
        int next = a + b;
        a = b;
        b = next;
    }

    // Now a is the largest Fibonacci number <= k
    int count = 0;
    while (k > 0) {
        if (a <= k) {
            k -= a;
            count++;
        }
        int temp = b - a;
        b = a;
        a = temp;
    }

    return count;
}

