public int findMinFibonacciNumbers(int k) {
    if (k < 1) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    // Generate Fibonacci numbers up to k
    int a = 1, b = 1;
    while (b <= k) {
        int next = a + b;
        a = b;
        b = next;
    }

    // b is now the smallest Fibonacci number greater than k, so we use the previous one
    int count = 0;
    while (k > 0) {
        // Find the largest Fibonacci number less than or equal to k
        while (a > k) {
            int temp = a;
            a = b - a;
            b = temp;
        }
        k -= a;
        count++;
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }

    // Generate all Fibonacci numbers less than or equal to k
    int a = 1, b = 1;
    while (b <= k) {
        int temp = b;
        b += a;
        a = temp;
    }

    // Subtract the largest Fibonacci number from k and recurse
    return 1 + findMinFibonacciNumbers(k - a);
}

