    int a = 1, b = 1;
    while (b <= k) {
        int temp = b;
        b = a + b;
        a = temp;
    }

    // Count the number of Fibonacci numbers needed to sum up to k
    int count = 0;
    while (k > 0) {
        if (a <= k) {
            k -= a;
            count++;
        }
        int temp = a;
        a = b - a;
        b = temp;
    }

    return count;
}

