    if (n <= 0 || k <= 0) {
        throw new IllegalArgumentException("Both n and k must be positive integers.");
    }

    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
        }
    }
    return -1;
}

