public int maxUniqueSplit(String s) {
    return backtrack(s, new HashSet<String>(), 0);
}

private int backtrack(String s, HashSet<String> seen, int start) {
    if (start == s.length()) {
        return 0;
    }
    int maxUnique = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String substring = s.substring(start, end);
        if (!seen.contains(substring)) {
            seen.add(substring);
            maxUnique = Math.max(maxUnique, 1 + backtrack(s, seen, end));
            seen.remove(substring);
        }
    }
    return maxUnique;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    return backtrack(s, 0, new HashSet<>());
}

private int backtrack(String s, int start, HashSet<String> uniqueSubstrings) {
    if (start == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String currentSubstring = s.substring(start, end);
        if (!uniqueSubstrings.contains(currentSubstring)) {
            uniqueSubstrings.add(currentSubstring);
            max = Math.max(max, 1 + backtrack(s, end, uniqueSubstrings));
            uniqueSubstrings.remove(currentSubstring);
        }
    }
    return max;
}

