public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remaining = n;
    while (remaining > 0) {
        for (char c = 'a'; c <= 'z'; c++) {
            int value = c - 'a' + 1;
            if (remaining == 1) {
                if (k == value) {
                    result.append(c);
                    remaining--;
                    break;
                }
            } else {
                int maxPossibleValue = value + (remaining - 1) * 26;
                if (k <= maxPossibleValue) {
                    result.append(c);
                    k -= value;
                    remaining--;
                    break;
                }
            }
        }
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < n; i++) {
        result.append('a');
    }
    k -= n;

    for (int i = n - 1; i >= 0 && k > 0; i--) {
        int addVal = Math.min(25, k);
        result.setCharAt(i, (char) ('a' + addVal));
        k -= addVal;
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int currentSum = 0;

    for (int i = 0; i < n; i++) {
        // Try to place 'a' if possible
        if (currentSum + 1 + (n - i - 1) * 26 >= k) {
            result.append('a');
            currentSum += 1;
        } else {
            // Place the largest possible character
            int remainingValue = k - (currentSum + (n - i - 1) * 1);
            char ch = (char) ('a' + remainingValue - 1);
            result.append(ch);
            currentSum += remainingValue;
            break;
        }
    }

    // Fill the rest with 'z'
    while (result.length() < n) {
        result.append('z');
    }

    return result.toString();
}

