    // Reverse the digits after (i)
    int left = i + 1;
    int right = length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert the character array back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        // This exception should not occur given the constraints
        return -1;
    }
