private static List<String> helper(int currentLength, int targetLength) {
    if (currentLength == 0) {
        return Collections.singletonList("");
    }
    if (currentLength == 1) {
        return Arrays.asList("0", "1", "8");
    }

    List<String> subResult = helper(currentLength - 2, targetLength);
    List<String> result = new ArrayList<>();

    for (String s : subResult) {
        if (currentLength != targetLength) {
            result.add("0" + s + "0");
        }
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }

    return result;
}

