public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n < 1) {
        return result;
    }

    for (int i = 1; i <= 9; i++) {
        dfs(result, i, n);
    }
    return result;
}

private static void dfs(List<Integer> result, int current, int n) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int i = 0; i <= 9; i++) {
        dfs(result, current * 10 + i, n);
    }
}

